package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"io/fs"
	"maps"
	"os"
	"path/filepath"
	"strings"
)

// The frontend is embedded into production builds without touching the
// project: `go build -overlay` adds a generated file to the app's package
// that embeds the frontendDist files, which the overlay maps into a
// directory of the package, and hands them to mygo.SetFrontend. The names of
// the generated files start with 0 to sort before the app's own: the go
// tool presents the files in the order of their names, and so runs their init
// functions, and a SetFrontend of the app's must come after the generated
// one to win.
const (
	frontendGenFile = "0mygo_frontend_gen.go"
	frontendGenDir  = "mygo_frontend"
)

const frontendGenSource = `// Code generated by mygo build. DO NOT EDIT.

package main

import (
	"embed"
	"io/fs"

	"github.com/egoist/mygo"
)

//go:embed all:` + frontendGenDir + `
var mygoFrontendFiles embed.FS

func init() {
	files, _ := fs.Sub(mygoFrontendFiles, "` + frontendGenDir + `")
	mygo.SetFrontend(files)
}
`

// `mygo dev` serves the frontendDist files from disk when it has no dev
// server (MYGO_FRONTEND_DIST), so that edits show on reload. An app links the
// code that serves mygo:// only when it calls mygo.SetFrontend, so the dev
// build adds a file, through the same overlay, that calls it with those
// files.
const devFrontendGenFile = "0mygo_devfrontend_gen.go"

const devFrontendGenSource = `// Code generated by mygo dev. DO NOT EDIT.

package main

import (
	"os"

	"github.com/egoist/mygo"
)

func init() {
	if dir := os.Getenv("MYGO_FRONTEND_DIST"); dir != "" {
		mygo.SetFrontend(os.DirFS(dir))
	}
}
`

// devServesFrontendDist reports whether `mygo dev` serves frontendDist from
// disk: it has no dev server to point the app at.
func devServesFrontendDist(c *Config) bool { return c.DevURL == "" && c.FrontendDist != "" }

// devFrontendFiles returns the overlay entries that make the dev build of the
// app in pkg serve MYGO_FRONTEND_DIST, writing the generated source into
// work. It returns nothing when `mygo dev` does not serve frontendDist.
func devFrontendFiles(c *Config, pkg, work string) (map[string]string, error) {
	replace := map[string]string{}
	if !devServesFrontendDist(c) {
		return replace, nil
	}
	if _, err := os.Lstat(filepath.Join(pkg, devFrontendGenFile)); err == nil {
		return nil, fmt.Errorf("%s is in the way of serving the frontend; rename it", filepath.Join(pkg, devFrontendGenFile))
	}
	gen := filepath.Join(work, devFrontendGenFile)
	if err := os.WriteFile(gen, []byte(devFrontendGenSource), 0o644); err != nil {
		return nil, err
	}
	replace[filepath.Join(pkg, devFrontendGenFile)] = gen
	return replace, nil
}

// An app with updates in mygo.config.ts needs the HTTP feed of mygo.Updater,
// which package mygo does not link (importing net/http costs an app 2.2
// MB): the build adds a file that imports it, through the same overlay.
const updateFeedGenFile = "0mygo_updates_gen.go"

const updatefeedPackage = "github.com/egoist/mygo/updatefeed"

const updateFeedGenSource = `// Code generated by mygo build. DO NOT EDIT.

package main

import _ "github.com/egoist/mygo/updatefeed"
`

// appHasPackage reports whether the module of MyGo that the app at c.root
// builds with has the package path. The files the CLI generates import
// packages of the CLI's version of MyGo; an app whose go.mod pins an older
// one does not have them, and the build would fail in a file the user did
// not write, with advice (go get) that cannot fix it. Such an app is built
// as it was, with what its MyGo gives it.
func appHasPackage(c *Config, path string) bool {
	cmd := goCommand(c.root, nil, "list", path)
	cmd.Stdout, cmd.Stderr = io.Discard, io.Discard
	return cmd.Run() == nil
}

// updateFeedFiles returns the overlay entry that links the HTTP feed of the
// updates into the main package in pkg, writing the generated source into
// work. It returns nothing when the app has no updates, or its MyGo has no
// updatefeed (an older one fetches the feed by itself).
func updateFeedFiles(c *Config, pkg, work string) (map[string]string, error) {
	replace := map[string]string{}
	if c.Updates == nil {
		return replace, nil
	}
	if !appHasPackage(c, updatefeedPackage) {
		logf("The MyGo of this app has no %s; its updates use the feed it has. Update MyGo (go get github.com/egoist/mygo@latest) to build as this CLI does.", updatefeedPackage)
		return replace, nil
	}
	if _, err := os.Lstat(filepath.Join(pkg, updateFeedGenFile)); err == nil {
		return nil, fmt.Errorf("%s is in the way of linking the update feed; rename it", filepath.Join(pkg, updateFeedGenFile))
	}
	gen := filepath.Join(work, updateFeedGenFile)
	if err := os.WriteFile(gen, []byte(updateFeedGenSource), 0o644); err != nil {
		return nil, err
	}
	replace[filepath.Join(pkg, updateFeedGenFile)] = gen
	return replace, nil
}

// frontendFiles returns the overlay entries that embed FrontendDist into
// the main package in pkg, writing the generated source into work. It
// returns nothing when the app has no frontend to embed.
func frontendFiles(c *Config, pkg, work string) (map[string]string, error) {
	replace := map[string]string{}
	if c.FrontendDist == "" {
		return replace, nil
	}
	dist := c.path(c.FrontendDist)
	for _, name := range []string{frontendGenFile, frontendGenDir} {
		if _, err := os.Lstat(filepath.Join(pkg, name)); err == nil {
			return nil, fmt.Errorf("%s is in the way of embedding the frontend; rename it", filepath.Join(pkg, name))
		}
	}
	err := filepath.WalkDir(dist, func(path string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if d.IsDir() || !d.Type().IsRegular() {
			return nil
		}
		rel, err := filepath.Rel(dist, path)
		if err != nil {
			return err
		}
		replace[filepath.Join(pkg, frontendGenDir, rel)] = path
		return nil
	})
	if os.IsNotExist(err) {
		return nil, fmt.Errorf("frontendDist %s does not exist; set buildCommand in %s to build it", c.FrontendDist, c.configName())
	}
	if err != nil {
		return nil, err
	}
	if len(replace) == 0 {
		return nil, fmt.Errorf("frontendDist %s is empty", c.FrontendDist)
	}
	gen := filepath.Join(work, frontendGenFile)
	if err := os.WriteFile(gen, []byte(frontendGenSource), 0o644); err != nil {
		return nil, err
	}
	replace[filepath.Join(pkg, frontendGenFile)] = gen
	return replace, nil
}

// mergeFiles returns the overlay entries of both maps.
func mergeFiles(a, b map[string]string) map[string]string {
	out := maps.Clone(a)
	if out == nil {
		out = map[string]string{}
	}
	maps.Copy(out, b)
	return out
}

// writeOverlay writes a go build -overlay file, or returns "" when there is
// nothing to overlay.
func writeOverlay(path string, replace map[string]string) (string, error) {
	if len(replace) == 0 {
		return "", nil
	}
	data, err := json.Marshal(struct{ Replace map[string]string }{replace})
	if err != nil {
		return "", err
	}
	return path, os.WriteFile(path, data, 0o644)
}

// packageDir returns the directory of the app's main package.
func packageDir(c *Config) (string, error) {
	var out bytes.Buffer
	cmd := goCommand(c.root, nil, "list", "-f", "{{.Dir}}", c.Main)
	cmd.Stdout = &out
	if err := cmd.Run(); err != nil {
		return "", fmt.Errorf("go list %s: %w", c.Main, err)
	}
	return strings.TrimSpace(out.String()), nil
}
